    'internal/agent/loop.go': [
      'package agent',
      '',
      'import (',
      '\t"context"',
      '\t"errors"',
      '\t"fmt"',
      '',
      '\t"craftwork/internal/model"',
      '\t"craftwork/internal/store"',
      ')',
      '',
      'const (',
      '\tMaxModelCalls = 200',
      '\tMaxToolCalls  = 100',
      ')',
      '',
      '// Run 驱动一次从用户消息到最终回复的循环。',
      'type Run struct {',
      '\tID       string',
      '\tThreadID string',
      '\tModel    model.Client',
      '\tTools    *Registry',
      '\tStore    *store.DB',
      '\tCtx      context.Context',
      '}',
      '',
      'func (r *Run) Execute(input string) error {',
      '\tmessages := []model.Message{{Role: model.RoleUser, Text: input}}',
      '\tfor call := 0; call < MaxModelCalls; call++ {',
      '\t\tselect {',
      '\t\tcase <-r.Ctx.Done():',
      '\t\t\treturn r.Ctx.Err()',
      '\t\tdefault:',
      '\t\t}',
      '',
      '\t\treply, err := r.Model.Stream(r.Ctx, messages)',
      '\t\tif err != nil {',
      '\t\t\treturn fmt.Errorf("model stream: %w", err)',
      '\t\t}',
      '\t\tmessages = append(messages, reply)',
      '\t\tif len(reply.ToolCalls) == 0 {',
      '\t\t\treturn nil',
      '\t\t}',
      '',
      '\t\tfor _, call := range reply.ToolCalls {',
      '\t\t\tresult, err := r.Tools.Invoke(r.Ctx, call)',
      '\t\t\tif errors.Is(err, ErrApprovalRequired) {',
      '\t\t\t\treturn r.requestApproval(call)',
      '\t\t\t}',
      '\t\t\tmessages = append(messages, model.ToolResult(call.ID, result))',
      '\t\t}',
      '\t}',
      '\treturn ErrTooManyCalls',
      '}',
    ].join('\n'),

    'internal/agent/tools.go': [
      'package agent',
      '',
      'import (',
      '\t"context"',
      '\t"fmt"',
      '\t"os"',
      '\t"path/filepath"',
      ')',
      '',
      'type Tool struct {',
      '\tName        string',
      '\tDescription string',
      '\tRisk        Risk',
      '\tHandler     func(context.Context, map[string]any) (string, error)',
      '}',
      '',
      'type Registry struct {',
      '\tworkspace string',
      '\ttools     map[string]Tool',
      '\tpolicy    *Policy',
      '}',
      '',
      'func (r *Registry) Register(t Tool) {',
      '\tr.tools[t.Name] = t',
      '}',
      '',
      'func (r *Registry) Invoke(ctx context.Context, call ToolCall) (string, error) {',
      '\ttool, ok := r.tools[call.Name]',
      '\tif !ok {',
      '\t\treturn "", fmt.Errorf("unknown tool: %s", call.Name)',
      '\t}',
      '\tif err := r.policy.Check(tool, call.Args); err != nil {',
      '\t\treturn "", err',
      '\t}',
      '\treturn tool.Handler(ctx, call.Args)',
      '}',
      '',
      '// resolve 做安全拼接，拒绝工作区外路径与符号链接逃逸。',
      'func (r *Registry) resolve(rel string) (string, error) {',
      '\tabs, err := filepath.Abs(filepath.Join(r.workspace, rel))',
      '\tif err != nil {',
      '\t\treturn "", err',
      '\t}',
      '\treal, err := filepath.EvalSymlinks(abs)',
      '\tif err != nil && !os.IsNotExist(err) {',
      '\t\treturn "", err',
      '\t}',
      '\tif !strings.HasPrefix(real, r.workspace+string(os.PathSeparator)) {',
      '\t\treturn "", ErrPathOutsideWorkspace',
      '\t}',
      '\treturn real, nil',
      '}',
    ].join('\n'),

    'internal/store/db.go': [
      'package store',
      '',
      'import (',
      '\t"database/sql"',
      '\t"errors"',
      '\t"time"',
      ')',
      '',
      'var ErrMigrateFailed = errors.New("migration failed")',
      '',
      'type DB struct {',
      '\tsql *sql.DB',
      '\tnow func() time.Time',
      '}',
      '',
      'func Open(path string) (*DB, error) {',
      '\tdb, err := sql.Open("sqlite", path+"?_busy_timeout=5000&_journal_mode=WAL")',
      '\tif err != nil {',
      '\t\treturn nil, err',
      '\t}',
      '\tdb.SetMaxOpenConns(4)',
      '\tdb.SetMaxIdleConns(2)',
      '\treturn &DB{sql: db, now: time.Now}, nil',
      '}',
      '',
      'func (d *DB) Close() error { return d.sql.Close() }',
      '',
      '// Migrate 在事务中执行版本迁移，失败时回滚并拒绝启动。',
      'func (d *DB) Migrate(target int) error {',
      '\ttx, err := d.sql.Begin()',
      '\tif err != nil {',
      '\t\treturn err',
      '\t}',
      '\tdefer tx.Rollback()',
      '\tfor v := currentVersion(tx); v < target; v++ {',
      '\t\tif err := migrations[v+1](tx); err != nil {',
      '\t\t\treturn fmt.Errorf("%w: v%d", ErrMigrateFailed, v+1)',
      '\t\t}',
      '\t}',
      '\treturn tx.Commit()',
      '}',
    ].join('\n'),

